public static boolean canAttackRecruit(LivingEntity attacker, AbstractRecruitEntity targetRecruit) {
        if (attacker.equals(targetRecruit)) return false;

        if (attacker instanceof AbstractRecruitEntity attackerRecruit) {
            // Same player owner → never attack
            if (attackerRecruit.isOwned() && targetRecruit.isOwned() &&
                    attackerRecruit.getOwnerUUID().equals(targetRecruit.getOwnerUUID())) {
                return false;
            }

            // Same scoreboards team with friendly fire off → never attack
            if (attackerRecruit.getTeam() != null && targetRecruit.getTeam() != null &&
                    attackerRecruit.getTeam().equals(targetRecruit.getTeam()) &&
                    !attackerRecruit.getTeam().isAllowFriendlyFire()) {
                return false;
            }

            // Same patrol group (protectUUID points to same leader) → never attack
            if (attackerRecruit.getProtectUUID() != null &&
                    attackerRecruit.getProtectUUID().equals(targetRecruit.getProtectUUID())) {
                return false;
            }

            // Same RecruitsGroup UUID → never attack (covers NPC patrol units with no owner/team)
            if (attackerRecruit.getGroup() != null &&
                    attackerRecruit.getGroup().equals(targetRecruit.getGroup())) {
                return false;
            }

            if(targetRecruit instanceof MessengerEntity messenger && messenger.isAtMission()) return false;
        }

        return canHarmTeam(attacker, targetRecruit);
    }

public static boolean canAttackPlayer(LivingEntity attacker, Player player) {
        if (attacker instanceof AbstractRecruitEntity recruit) {
            if(player.getUUID().equals(recruit.getOwnerUUID())
                    || player.getUUID().equals(recruit.getProtectUUID())
                    || player.isCreative()
                    || player.isSpectator()
            )
                return false;
        }
        return canHarmTeam(attacker, player);
    }

public static boolean canAttackAnimal(LivingEntity attacker, Animal animal) {
        if (attacker instanceof AbstractRecruitEntity recruit ){
            if(recruit.getVehicle() != null && recruit.getVehicle().getUUID().equals(animal.getUUID())) return false;

            if (recruit.getProtectUUID() != null && recruit.getProtectUUID().equals(recruit.getProtectUUID())) return false;

            if(animal.isVehicle()){
                if(animal.getFirstPassenger() instanceof AbstractRecruitEntity targetRecruit) return canAttackRecruit(attacker, targetRecruit);
                if(animal.getFirstPassenger() instanceof Player playerTarget) return canAttackPlayer(attacker, playerTarget);
            }
        }
        return canHarmTeam(attacker, animal);
    }

public static boolean canHarmTeam(LivingEntity attacker, LivingEntity target) {
        Team attackerTeam = attacker.getTeam();
        Team targetTeam = target.getTeam();

        if (attackerTeam == null || targetTeam == null) return true;

        if (attackerTeam.equals(targetTeam) && !attackerTeam.isAllowFriendlyFire()) return false;

        if (isAlly(attackerTeam, targetTeam)) return false;

        if (FactionEvents.recruitsTreatyManager != null && FactionEvents.recruitsTreatyManager.hasTreaty(attackerTeam.getName(), targetTeam.getName())) {
            return false;
        }

        return true;
    }

@SubscribeEvent
    public void onLivingAttack(LivingAttackEvent event) {
        if(event.getEntity().getCommandSenderWorld().isClientSide()) return;

        Entity target = event.getEntity();
        Entity source = event.getSource().getEntity();

        if (!target.getCommandSenderWorld().isClientSide() && target instanceof LivingEntity livingTarget && source instanceof LivingEntity livingSource) {
            if (!canAttack(livingSource, livingTarget)){
                event.setCanceled(true);
            }
            else{
                handleSignificantDamage(livingSource, livingTarget, event.getAmount(), (ServerLevel) livingTarget.getCommandSenderWorld());
            }
        }
    }

@SubscribeEvent
    public void onProjectileImpact(ProjectileImpactEvent event) {
        Entity entity = event.getEntity();
        HitResult rayTrace = event.getRayTraceResult();

        if (canceledProjectiles.contains(entity)) {
            return;
        }

        if (!(entity instanceof Projectile projectile)) {
            return;
        }
        Entity owner = projectile.getOwner();

        if(owner == null) return;

        if (rayTrace.getType() != HitResult.Type.ENTITY) {
            return;
        }

        Entity impactEntity = ((EntityHitResult) rayTrace).getEntity();
        String encode = impactEntity.getEncodeId();
        if (encode != null && encode.contains("corpse:corpse")) {
            event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
            return;
        }

        if (!(impactEntity instanceof LivingEntity impactLiving)) {
            return;
        }

        if (projectile instanceof AbstractArrow arrow && arrow.getPierceLevel() > 0) {

            if (owner instanceof LivingEntity livingOwner && !canAttack(livingOwner, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                canceledProjectiles.add(projectile);
                return;
            }
        }

        if (owner instanceof AbstractRecruitEntity recruit) {

            if (impactLiving instanceof Animal animal) {
                Entity passenger = animal.getFirstPassenger();
                if (passenger instanceof AbstractRecruitEntity passengerRecruit) {
                    if (!canAttack(recruit, passengerRecruit)) {

                        event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                        return;
                    }
                }
                else if (passenger instanceof Player player) {
                    if (!canAttack(recruit, player)) {

                        event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                        return;
                    }
                }
            }

            if (!canAttack(recruit, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                return;
            }
            else {
                recruit.addXp(2);
                recruit.checkLevel();
            }
        }

        if (owner instanceof AbstractIllager illager && !RecruitsServerConfig.PillagerFriendlyFire.get()) {
            if (illager.isAlliedTo(impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                canceledProjectiles.add(projectile);
                return;
            }
        }

        if (owner instanceof Player player) {
            if (!canHarmTeam(player, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                return;
            }
        }
    }

@SubscribeEvent
    public void onLivingHurt(LivingHurtEvent event) {
        if(event.getEntity().getCommandSenderWorld().isClientSide()) return;

        if (Main.isMusketModLoaded) {
            Entity sourceEntity = event.getSource().getEntity();
            if (sourceEntity instanceof AbstractRecruitEntity owner && IWeapon.isMusketModWeapon(owner.getMainHandItem())) {
                Entity target = event.getEntity();
                if (target instanceof LivingEntity impactEntity) {

                    if (!canAttack(owner, impactEntity)) {
                        event.setCanceled(true);
                    } else {
                        owner.addXp(2);
                        owner.checkLevel();
                    }
                }
            }
        }

        Entity target = event.getEntity();
        Entity source = event.getSource().getEntity();
        if (source instanceof LivingEntity sourceEntity) {
            alertTeam(target, sourceEntity);
        }
    }

public static void alertTeam(Entity target, LivingEntity attacker) {
        if (target.getTeam() == null) return;

        target.getCommandSenderWorld().getEntitiesOfClass(
                AbstractRecruitEntity.class,
                target.getBoundingBox().inflate(32D),
                (recruit) -> recruit.getTarget() == null &&
                        recruit.getTeam() != null &&
                        recruit.getTeam().equals(target.getTeam())
        ).forEach((recruit) -> recruit.setTarget(attacker));
    }

public boolean shouldAttack(LivingEntity target) {
        return switch (this.getState()) {
            case 3 -> false; // Passive mode: never attack
            case 0 -> shouldAttackOnNeutral(target) && canAttack(target);
            case 1 -> (shouldAttackOnNeutral(target) || shouldAttackOnAggressive(target)) && canAttack(target);
            case 2 -> !RecruitEvents.isAlly(this.getTeam(), target.getTeam()) && canAttack(target);
            default -> canAttack(target);
        };
    }

private void searchForTargetsSync(ServerLevel serverLevel) {
        AABB searchBox = this.getBoundingBox().inflate(40);
        List<LivingEntity> nearby = serverLevel.getEntitiesOfClass(
                LivingEntity.class,
                searchBox,
                potTarget -> potTarget != this && targetingConditions.test(this, potTarget) && !AttackUtil.isTooDeepUnderwater(potTarget)
        );

        if (nearby.isEmpty()) return;

        nearby.sort(Comparator.comparingDouble(e -> e.distanceToSqr(this)));

        int pool = Math.min(10, nearby.size());
        LivingEntity target = nearby.get(this.getRandom().nextInt(pool));
        this.setTarget(target);
    }

public void tick() {
        super.tick();
        if(this.level().isClientSide()) return;

        this.collision.tick();

        if(despawnTimer > 0) despawnTimer--;
        if(despawnTimer == 0) recruitCheckDespawn();

        if(RecruitsServerConfig.RecruitsPayment.get()){
            if(paymentTimer > 0) paymentTimer--;
            if(paymentTimer == 0) {
                if(getUpkeepPos() != null || getUpkeepUUID() != null) forcedUpkeep = true;
                else checkPayment(this.getInventory());
            }
        }

        if(getMountTimer() > 0) setMountTimer(getMountTimer() - 1);
        if(getUpkeepTimer() > 0) setUpkeepTimer(getUpkeepTimer() - 1);
        if(remountAfterUpkeep && (this.tickCount + this.getId()) % 20 == 0 && !needsToGetFood()) tryRemountAfterUpkeep();
        // a Small Ships ground cannon pulls everyone touching it into its barrel - recruits are never its ammo
        if(this.getVehicle() != null && GroundCannon.isGroundCannon(this.getVehicle())) GroundCannon.handleRecruitInBarrel(this, this.getVehicle());
        if(getHunger() >=  70F && getHealth() < getMaxHealth()){
            this.heal(1.0F/50F);// 1 hp in 2.5s
        }

        if(this.reachedMovePos){
            this.setFollowState(2);
            this.reachedMovePos = false;
        }

        if(this.attackCooldown > 0) this.attackCooldown--;


        if(this.isAlive() && this.getState() != 3 && (this.tickCount + getTickPhase()) % getTargetSearchInterval() == 0){
            this.searchForTargets();
        }

        LivingEntity currentTarget = this.getTarget();
        if(currentTarget != null && (currentTarget.isDeadOrDying() || currentTarget.isRemoved())) this.setTarget(null);

        else if(currentTarget != null && (this.tickCount + getTickPhase()) % 10 == 0 && AttackUtil.isTooDeepUnderwater(currentTarget)){
            // the target dove deeper than allowed after it was acquired
            this.setTarget(null);
        }
            // Option 2 safety net: drop a target that is no longer visible, covering the case where a
            // recruit saw an enemy but lost sight before any attack/move goal took over (e.g. target
            // stepped behind cover while still out of melee range). Throttled so that, in the worst
            // case where no goal queried line of sight this tick, we don't run a raycast every tick per
            // recruit. EntitySensing caches per tick, so when a goal already queried LoS this is free.
        else if(currentTarget != null && (this.tickCount + getTickPhase()) % 10 == 0 && !this.getSensing().hasLineOfSight(currentTarget)){
            this.setTarget(null);
        }

        // Handle face rotation command
        if(this.rotateTicks > 0) {
            if(this.getNavigation().isDone()) {
                this.setYRot(this.ownerRot);
                this.yRotO = this.ownerRot;
                this.rotateTicks--;
            }
        }

    }

public boolean hire(Player player, RecruitsGroup group, boolean message) {
        if (!this.getCommandSenderWorld().isClientSide()) {
            RecruitEvent.Hired hireEvent = new RecruitEvent.Hired(this, player);
            MinecraftForge.EVENT_BUS.post(hireEvent);
            if (hireEvent.isCanceled()) return false;
        }
        String name = this.getName().getString() + ": ";
        Team ownerTeam = player.getTeam();// player is the new owner
        String stringId = ownerTeam != null ? ownerTeam.getName() : "";
        if (!RecruitEvents.recruitsPlayerUnitManager.canPlayerRecruit(stringId, player.getUUID())) {

            player.sendSystemMessage(INFO_RECRUITING_MAX(name));
            return false;
        }
        else {
            this.makeHireSound();

            this.resetPaymentTimer();
            this.setOwnerUUID(Optional.of(player.getUUID()));
            this.setIsOwned(true);
            this.navigation.stop();
            this.setTarget(null);
            this.setFollowState(2);
            this.setAggroState(0);
            if(group != null) this.setGroupUUID(group.getUUID());
            this.despawnTimer = -1;

            if(!this.getCommandSenderWorld().isClientSide()){
                RecruitEvents.recruitsPlayerUnitManager.addRecruits(player.getUUID(), 1);

                if(group != null){
                    RecruitEvents.recruitsGroupsManager.addMember(group.getUUID(), this.getUUID(),  (ServerLevel) this.getCommandSenderWorld());
                    RecruitEvents.recruitsGroupsManager.broadCastGroupsToPlayer(player);
                }

                if(ownerTeam != null){
                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                }
            }

            if(message){
                int i = this.random.nextInt(4);
                switch (i) {
                    default -> {
                        player.sendSystemMessage(TEXT_RECRUITED1(name));
                    }
                    case 2 -> {
                        player.sendSystemMessage(TEXT_RECRUITED2(name));
                    }
                    case 3 -> {
                        player.sendSystemMessage(TEXT_RECRUITED3(name));
                    }
                }
            }
        }

        return true;
    }

public void disband(@Nullable Player player, boolean keepTeam, boolean increaseCost){
        if (!this.getCommandSenderWorld().isClientSide()) {
            RecruitEvent.Dismissed dismissEvent = new RecruitEvent.Dismissed(this, player, keepTeam);
            MinecraftForge.EVENT_BUS.post(dismissEvent);
            if (dismissEvent.isCanceled()) return;
        }
        String name = this.getName().getString();

        if(player != null){
            player.sendSystemMessage(TEXT_DISBAND(name));
        }

        this.setTarget(null);
        this.setIsOwned(false);

        if(increaseCost) this.recalculateCost();

        if(this.getCommandSenderWorld().isClientSide()) return;
        // garrison recruits are not counted for the player (Governor, Variante B)
        if(!this.isGarrison()) RecruitEvents.recruitsPlayerUnitManager.removeRecruits(this.getOwnerUUID(), 1);
        if(this.isGarrison()){
            this.setGarrisonClaim(null);
            this.setListen(true);
        }
        this.setOwnerUUID(Optional.empty());

        if (this.getTeam() != null && !keepTeam){
            FactionEvents.removeRecruitFromTeam(this, this.getTeam(), (ServerLevel) this.getCommandSenderWorld());
        }

        if(this.getGroup() != null){
            RecruitEvents.recruitsGroupsManager.removeMember(this.getGroup(), this.getUUID(), (ServerLevel) this.getCommandSenderWorld());
            this.setGroupUUID(null);
        }
    }

public void assignToPlayer(UUID newOwner, UUID newGroupUUID){
        RecruitsGroup currentGroup = RecruitEvents.recruitsGroupsManager.getGroup(this.getGroup());
        if(currentGroup != null){
            currentGroup.removeMember(this.getUUID());
        }

        this.setGroupUUID(newGroupUUID);
        RecruitsGroup newGroup = RecruitEvents.recruitsGroupsManager.getGroup(newGroupUUID);

        this.disband(null, false, false);

        this.setOwnerUUID(Optional.of(newOwner));

        if(getOwner() != null){
            this.hire(getOwner(), newGroup, true);
            this.setFollowState(1);
        }
    }

public void updateTeam(){
        if(this.isOwned() && !this.getCommandSenderWorld().isClientSide()){
            Player owner = getOwner();
            if(owner != null) {
                Team recruitTeam = this.getTeam();
                Team ownerTeam = owner.getTeam();

                if (ownerTeam == null) {
                    if(recruitTeam != null){
                        //Remove from current team because ownerTeam is null
                        FactionEvents.removeRecruitFromTeam(this, recruitTeam, (ServerLevel) this.getCommandSenderWorld());
                        FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), recruitTeam.getName(), -1 );
                    }
                    //recruit team is also null, so no do nothing
                    needsTeamUpdate = false;
                }
                else if(recruitTeam == null){
                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), ownerTeam.getName(), +1 );
                    needsTeamUpdate = false;
                }
                else if(recruitTeam == ownerTeam){
                    updateColor(ownerTeam.getName());
                    needsTeamUpdate = false;
                }
                else{
                    FactionEvents.removeRecruitFromTeam(this, recruitTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), recruitTeam.getName(), -1 );

                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), ownerTeam.getName(), +1 );
                    needsTeamUpdate = false;
                }
            }
        }
    }

public boolean isEffectedByCommand(UUID player_uuid, UUID group) {
        if (!this.isOwned() || !this.isAlive() || !this.getListen()) return false;
        if (this.isGarrison()) return false;

        if (!this.getOwnerUUID().equals(player_uuid)) return false;

        if (group == null) {
            return true;
        }

        return this.getGroup() != null && this.getGroup().equals(group);
    }

public void setAggroState(int state) {
        switch (state){
            case 0:
            case 3:
                setTarget(null);//wird nur 1x aufgerufen
                break;
            case 1:
                break;
            case 2:
                setFollowState(0);
                break;
        }
        entityData.set(STATE, state);
    }

public void setFollowState(int state){
        switch (state) {
            case 0,6 -> {
                setShouldFollow(false);
                setShouldHoldPos(false);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 1 -> {
                setShouldFollow(true);
                setShouldHoldPos(false);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 2 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                clearHoldPos();
                setHoldPos(position());
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 3 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 4 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                clearHoldPos();
                setHoldPos(this.getOwner().position());
                setShouldProtect(false);
                setShouldMovePos(false);
                state = 3;
            }
            case 5 -> {
                setShouldFollow(false);
                setShouldHoldPos(false);
                setShouldProtect(true);
                setShouldMovePos(false);
            }
        }

        this.entityData.set(FOLLOW_STATE, state);
    }

public void reactToHit(@Nullable Entity attacker) {
        if(this.getMorale() > 0) this.setMoral(this.getMorale() - 0.25F);

        if(attacker instanceof LivingEntity living && RecruitEvents.canAttack(this, living)){
            if(this.getFollowState() == 5){//Protecting
                List<AbstractRecruitEntity> list = this.getCommandSenderWorld().getEntitiesOfClass(AbstractRecruitEntity.class, this.getBoundingBox().inflate(32D));
                for(AbstractRecruitEntity recruit : list){
                    if (recruit.getUUID().equals(recruit.getProtectUUID()) && recruit.isAlive() && !recruit.equals(living)){
                        //Patrolleader
                        recruit.setTarget(living);
                    }
                }
            }


            if(this.getTarget() != null){
                double d1 = this.distanceToSqr(this.getTarget());
                double d2 = this.distanceToSqr(living);

                if(d2 < d1) this.setTarget(living);
            }
            else
                this.setTarget(living);

            if(this.getShouldProtect() && this.getProtectingMob() instanceof AbstractRecruitEntity patrolLeader){
                patrolLeader.setTarget(living);
            }
        }
    }

public boolean doHurtTarget(@NotNull Entity entity) {
        float f = (float)this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        if (entity instanceof LivingEntity) {
            f += EnchantmentHelper.getDamageBonus(this.getMainHandItem(), ((LivingEntity)entity).getMobType());
        }

        int i = EnchantmentHelper.getFireAspect(this);
        if (i > 0) {
            entity.setSecondsOnFire(i * 4);
        }

        boolean flag = entity.hurt(this.damageSources().mobAttack(this), f);
        if (flag) {

            this.doEnchantDamageEffects(this, entity);
            this.setLastHurtMob(entity);
        }
        this.addXp(1);
        if(this.getHunger() > 0) this.setHunger(this.getHunger() - 0.1F);
        this.checkLevel();
        if(this.getMorale() < 100) this.setMoral(this.getMorale() + 0.25F);
        this.damageMainHandItem();
        return true;
    }

private boolean canAssign(ServerPlayer sender, AbstractRecruitEntity recruit) {
        if (recruit instanceof GovernorEntity) {
            sender.sendSystemMessage(Component.translatable("chat.recruits.governor.cannot_take_over", recruit.getName().getString()));
            return false;
        }
        boolean isOwner = sender.getUUID().equals(recruit.getOwnerUUID());
        if (isOwner) {
            if (recruit.isGarrison()) {
                sender.sendSystemMessage(Component.translatable("chat.recruits.governor.release_first", recruit.getName().getString()));
                return false;
            }
            return true;
        }

        String factionId = recruit.getTeam() != null ? recruit.getTeam().getName() : null;
        boolean isLeader = factionId != null && sender.getTeam() != null && factionId.equals(sender.getTeam().getName())
                && GovernorManager.isFactionLeader(factionId, sender.getUUID());
        if (!isLeader || !sender.getUUID().equals(this.newOwner)) return false;

        if (!RecruitEvents.recruitsPlayerUnitManager.canPlayerRecruit(factionId, sender.getUUID())) {
            sender.sendSystemMessage(Component.translatable("chat.recruits.governor.release_limit", recruit.getName().getString()));
            return false;
        }
        return true;
    }

protected void alertOthers() {
        double d0 = this.getFollowDistance();
        AABB axisalignedbb = AABB.unitCubeFromLowerCorner(this.recruit.position())
                .inflate(d0, 16.0D, d0);
        List<? extends AbstractRecruitEntity> list = this.recruit.getCommandSenderWorld()
                .getEntitiesOfClass(this.recruit.getClass(), axisalignedbb);

        for (AbstractRecruitEntity recruitToAlert : list) {
            if (this.recruit == recruitToAlert ||
                    recruitToAlert.getTarget() != null ||
                    this.recruit.getLastHurtByMob() == null ||
                    this.recruit.getLastHurtByMob() == null ||
                    recruitToAlert.getOwnerUUID() == null ||
                    !recruitToAlert.getOwnerUUID().equals(this.recruit.getOwnerUUID()) ||
                    recruitToAlert.isAlliedTo(this.recruit.getLastHurtByMob())) continue;

            boolean shouldIgnore = false;
            if (this.toIgnoreAlert != null) {
                for (Class<?> oclass : this.toIgnoreAlert) {
                    if (recruitToAlert.getClass() == oclass) {
                        shouldIgnore = true;
                        break;
                    }
                }
            }
            if (shouldIgnore) continue;

            this.alertOther(recruitToAlert, this.recruit.getLastHurtByMob());
        }
    }

private boolean canAttackHoldPos() {
        Vec3 pos = recruit.getHoldPos();
        LivingEntity target = this.recruit.getTarget();
        if (target != null && pos != null && recruit.getShouldHoldPos()) {
            double distanceToPos = target.distanceToSqr(pos);
            double ref = 400;

            return distanceToPos < ref;
        }
        return true;
    }

public boolean canContinueToUse() {
        LivingEntity target = this.recruit.getTarget();
        if (target == null || !target.isAlive()) {
            return false;
        } else if (!this.recruit.getSensing().hasLineOfSight(target)) {
            // Option 2: drop the target when line of sight is lost so the recruit does not keep
            // it queued while behind cover. The move-towards goal is also LoS-gated, so once sight
            // is gone nothing chases; the next search re-acquires only if the target becomes
            // visible again.
            this.recruit.setTarget(null);
            return false;
        } else {
            boolean canAttackHoldPos = canAttackHoldPos();
            boolean needsToGetFood = recruit.needsToGetFood();
            boolean getShouldMount = recruit.getShouldMount();
            boolean getShouldMovePos = recruit.getShouldMovePos();
            return (!(target instanceof Player) || !target.isSpectator() && !((Player) target).isCreative()) && canAttackHoldPos && recruit.getState() != 3 && !needsToGetFood && !getShouldMount && !getShouldMovePos;
        }
    }

public void tick() {
        if (this.pathingCooldown > 0) this.pathingCooldown--;

        this.recruit.tryJumpOverTerrain();

        LivingEntity target = this.recruit.getTarget();
        if (target != null && target.isAlive()) {
            this.recruit.getLookControl().setLookAt(target, 30.0F, 30.0F);
            double distanceToTarget = this.recruit.distanceToSqr(target.getX(), target.getY(), target.getZ());
            double reach = AttackUtil.getAttackReachSqr(recruit);

            boolean canSee = this.recruit.getSensing().hasLineOfSight(target);
            boolean isNotFollowing = !recruit.isFollowing();
            boolean coolDownElapsed = this.pathingCooldown <= 0;

            if (distanceToTarget <= reach && canSee) {
                if (isNotFollowing) this.recruit.getNavigation().stop();
                AttackUtil.performAttack(this.recruit, target);
            }
            else if (canSee && isNotFollowing && coolDownElapsed && !recruit.holdFormation) {
                this.pathingCooldown = 4 + this.recruit.getRandom().nextInt(4);

                if (distanceToTarget > 2024.0D) {
                    this.pathingCooldown += 10;
                } else if (distanceToTarget > 256.0D) {
                    this.pathingCooldown += 5;
                }
                this.recruit.getNavigation().moveTo(target, this.speedModifier);
            }
        }
    }

public void tick() {

        if(this.protectingMob != null) {

            boolean isClose = protectingMob.distanceTo(this.recruit) <= range;
            if(!isClose){
                if (--this.timeToRecalcPath <= 0) {
                    this.timeToRecalcPath = this.adjustedTickDelay(10);
                    recruit.getNavigation().moveTo(protectingMob, 1.15F);

                    if(this.recruit instanceof CaptainEntity captain && captain.getVehicle() instanceof Boat){
                        captain.setSailPos(this.protectingMob.getOnPos());
                    }
                }

                this.recruit.tryJumpOverTerrain();
            }
        }

        if (this.protectingMob == null || !protectingMob.isAlive()) {
            if(this.protectingMob != null && !protectingMob.isAlive()){
                if (recruit.getOwner() != null)recruit.getOwner().sendSystemMessage(TEXT_PROTECT_DIED(recruit.getName().getString()));
            }
            clear();
        }

        if(this.recruit.tickCount % 20 == 0){
            this.getProtecting();
            this.checkMounts();
        }
    }

public void tick() {
        if(target != null && target.isAlive()) {
            double distance = target.distanceToSqr(this.crossBowman);
            boolean isClose = distance <= 150;
            boolean isFar = distance >= 3500;
            boolean isTooFar = distance >= 4500;
            boolean inRange =  !isFar;
            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);

            if (canSee) {
                ++this.seeTime;
            } else {
                this.seeTime = 0;
            }

            if(isTooFar){
                this.crossBowman.setTarget(null);
                this.stop();
                return;
            }

            // movement
            if (crossBowman.getShouldFollow() && crossBowman.getOwner() != null) {
                handleFollow(this.crossBowman.getOwner(), inRange, isFar);
            }
            else if(crossBowman.getShouldHoldPos() && crossBowman.getHoldPos() != null){
                handleHoldPos(crossBowman.getHoldPos(), inRange);
            }
            else {
                handleWander(inRange, isFar, isClose);
            }
        }

        //WEAPON HANDLING
        if(isWeaponInMainHand()) {
            if(crossBowman.getShouldStrategicFire() && target == null) {
                BlockPos pos = crossBowman.getStrategicFirePos();
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (pos != null) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }

                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (pos != null) {
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(pos.getX(), pos.getY(), pos.getZ());

                            if (++this.seeTime > weapon.getWeaponLoadTime()) {
                                this.state = State.SHOOT;
                                this.seeTime = 0;
                            }
                        }
                    }

                    case SHOOT -> {
                        if (pos != null) {
                            this.weapon.performRangedAttackIWeapon(this.crossBowman, pos.getX(), pos.getY(), pos.getZ(), weapon.getProjectileSpeed());
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE; //RESUPPLY
                    }
                }
            }
            else {
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (target != null && target.isAlive()) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }
                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (target != null && target.isAlive()) {
                            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(target);

                            if (canSee) {
                                if (++this.seeTime >= weapon.getWeaponLoadTime()) {
                                    this.state = State.SHOOT;
                                    this.seeTime = 0;
                                }
                            } else if (crossBowman.getShouldHoldPos()) {
                                this.crossBowman.setTarget(null);
                            }
                        } else {
                            this.crossBowman.setAggressive(false);
                            seeTime = 0;
                        }
                    }

                    case SHOOT -> {
                        LivingEntity savedTarget = null;
                        if (target != null && target.isAlive() && this.crossBowman.canAttack(target) && this.crossBowman.getState() != 3) {
                            this.crossBowman.getLookControl().setLookAt(target);

                            if(AttackUtil.canPerformHorseAttack(this.crossBowman, target)){
                                if(target.getVehicle() instanceof LivingEntity) {
                                    savedTarget = target;
                                    target = (LivingEntity) target.getVehicle();
                                }
                            }

                            this.weapon.performRangedAttackIWeapon(this.crossBowman, target.getX(), target.getY() + target.getEyeHeight(), target.getZ(), weapon.getProjectileSpeed());

                            if(savedTarget != null){
                                target = savedTarget;
                            }

                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE;
                    }
                }
            }
        }
    }

public static void onAttackCommand(Player player, UUID player_uuid, List<AbstractRecruitEntity> list, UUID group) {
        HitResult hitResult = player.pick(100, 1F, false);
        BlockPos blockpos = null;
        AABB aabb = null;
        List<LivingEntity> targets = new ArrayList<>();
        if (hitResult.getType() == HitResult.Type.ENTITY){
            EntityHitResult entityHitResult = (EntityHitResult) hitResult;

            blockpos = entityHitResult.getEntity().getOnPos();
            if(entityHitResult.getEntity() instanceof LivingEntity living) targets.add(living);
        }
        else if (hitResult.getType() == HitResult.Type.BLOCK){
            BlockHitResult blockHitResult = (BlockHitResult) hitResult;
            blockpos = blockHitResult.getBlockPos();
        }
        else return;

        aabb = new AABB(blockpos).inflate(10);

        list.removeIf(recruit -> !recruit.isEffectedByCommand(player_uuid, group));

        List<LivingEntity> validTargets = player.getCommandSenderWorld()
                .getEntitiesOfClass(LivingEntity.class, aabb);

        if (list.isEmpty() || validTargets.isEmpty()) return;

        AbstractRecruitEntity firstRecruit = list.get(0);
        validTargets.removeIf(target -> !firstRecruit.canAttack(target));

        if (validTargets.isEmpty()) return;

        for (int i = 0; i < list.size(); i++) {
            AbstractRecruitEntity recruit = list.get(i);
            LivingEntity target = validTargets.get(i % validTargets.size());
            recruit.setTarget(target);
            recruit.setHoldPos(getEngageHoldPos(recruit, target));
            recruit.setFollowState(3);
        }
    }

@Override
    public void performRangedAttack(@NotNull LivingEntity target, float v) {
        if(this.level().isClientSide()) return;
        if (this.getMainHandItem().getItem() instanceof BowItem) {

            if(AttackUtil.canPerformHorseAttack(this, target)){
                if(target.getVehicle() instanceof LivingEntity) {
                    target = (LivingEntity) target.getVehicle();
                }
            }

            ItemStack itemstack = this.getProjectile(this.getItemInHand(InteractionHand.MAIN_HAND));

            AbstractArrow arrow = ProjectileUtil.getMobArrow(this, itemstack, v);
            arrow = ((net.minecraft.world.item.BowItem) this.getMainHandItem().getItem()).customArrow(arrow);

            int powerLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.POWER_ARROWS, itemstack);
            arrow.setBaseDamage(arrow.getBaseDamage() + (double) powerLevel * 0.5D + 0.5D + this.arrowDamageModifier());

            int punchLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.PUNCH_ARROWS, itemstack);
            if (punchLevel > 0) arrow.setKnockback(punchLevel);

            int fireLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FLAMING_ARROWS, itemstack);
            if (fireLevel > 0) arrow.setSecondsOnFire(100);

            double distance = this.distanceToSqr(target.getX(), target.getY(), target.getZ());
            double heightDiff = target.getY() - this.getY();

            double d0 = target.getX() - this.getX();
            double d1 = target.getY() - arrow.getY() + target.getEyeHeight();
            double d2 = target.getZ() - this.getZ();
            double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));

            double angle = IRangedRecruit.getAngleDistanceModifier(distance, 47, 4) + IRangedRecruit.getAngleHeightModifier(distance, heightDiff, 1.00D) / 100;
            float force = 1.90F + IRangedRecruit.getForceDistanceModifier(distance, 1.90F);
            double morale = this.getMorale();
            float accuracy = Math.max(6 - (float) (0.1F * morale), 0);
            //Main.LOGGER.info("Distance: " + distance);
                                                //angle   = 0.196F           //force     //accuracy 0 = 100%
            arrow.shoot(d0, d1 + d3 * angle, d2, force, accuracy);

            if(RecruitsServerConfig.RangedRecruitsNeedArrowsToShoot.get()){
                int k = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.INFINITY_ARROWS, this.getMainHandItem());
                if (k == 0) {
                    this.consumeArrow();
                    arrow.pickup = AbstractArrow.Pickup.ALLOWED;
                }
            }

            this.playSound(SoundEvents.ARROW_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));

            this.getCommandSenderWorld().addFreshEntity(arrow);

            this.damageMainHandItem();
        }
    }

public boolean canUse() {
        AABB aabb = this.recruit.getBoundingBox().inflate(30.0D, 8.0D, 30.0D);
        List<Villager> list = this.recruit.getCommandSenderWorld().getEntitiesOfClass(Villager.class, aabb, (livingEntity) -> !this.attackTargeting.test(this.recruit, livingEntity));

        List<Player> list1 = this.recruit.getCommandSenderWorld().getEntitiesOfClass(Player.class, aabb);

        for(Villager villager : list) {
            for(Player player : list1) {
                int i = villager.getPlayerReputation(player);
                if (i <= -100) {
                    this.potentialTarget = player;
                }
            }
        }

        if (this.potentialTarget == null) {
            return false;
        } else {
            return !(this.potentialTarget instanceof Player) || !this.potentialTarget.isSpectator() && !((Player)this.potentialTarget).isCreative();
        }
    }
